import React, { useMemo, useState, useEffect } from 'react';
import { useContexState } from '../hooks/context';

import api from '../services/api'

interface ConvertListParam {
    data: {
        id: number;
        number: number;
        name: string;
        phone: string;
        price: number;
        analyzed: number;
        created_at: string;
    }[]
};

interface ConvertListReturn {
    [key: string]: [{
        id: number;
        name: string;
        phone: string;
        price: number;
        analyzed: number;
        created_at: string;
    }]
};

interface Lines {
    firstCard: number;
    id: string;
};

export function useLoadPage() {
    const [isMounted, setIsMounted] = useState(false);

    const { setlistData, setCountAnalyzed, setGetList, setIsMountedApi, setResponceArray, isMountedApi, setLoginValue, setSelectedNumber } = useContexState();
    const { listData, perPage, getList, sortNumber } = useContexState();




    function convertList({ data }: ConvertListParam) {
        return data.reduce((h: ConvertListReturn, card) => {
            const user = {
                id: card.id,
                name: card.name,
                phone: card.phone,
                price: card.price,
                analyzed: card.analyzed,
                created_at: card.created_at,
            };
            return Object.assign(h, {
                [card.number]: (h[card.number] || []).concat(user)
            });
        }, {});
    };


    function limiterNumber(number: number) {
        if (number + (perPage * 6) - 1 < 9999) {
            return number + (perPage * 6) - 1
        } else {
            return 9999
        };
    };


    useEffect(() => {
        /*setLoginValue({
            name: 'James_TI',
            password: '1234',
            permission: 'adm'
        });*/

        if (isMounted) {
            setIsMounted(false);

            api.get("countCards", {}
            ).then((responce) => {
                setCountAnalyzed({
                    false: Number(responce.data[0]?.['count(*)']),
                    true: Number(responce.data[1]?.['count(*)'])
                });
            });

            if (sortNumber === 'default') {
                api.get("getCards", {
                    params: {
                        firstNumber: listData[0]?.firstCard,
                        lastNumber: limiterNumber(listData[0]?.firstCard),
                    }
                }
                ).then((responce) => {
                    setIsMountedApi(true);
                    console.log(JSON.stringify(responce.data));
                    setGetList(convertList(responce));
                    setResponceArray(responce.data)
                });
            };

            if (sortNumber === 'analyzed') {
                api.get("getAnalyzed", {
                    params: {
                        firstNumber: listData[0]?.firstCard,
                    }
                }
                ).then((responce) => {
                    setIsMountedApi(true);
                    console.log(JSON.stringify(responce.data));
                    setGetList(convertList(responce));
                    setResponceArray(responce.data)
                });
            };
        };
    }, [isMounted]);



    function LoadPage(value: number | number = 0) {
        const lines: Lines[] = [];
        setIsMountedApi(false);

        for (let i = 0; i < perPage; i++) {
            lines.push({ firstCard: i + value, id: String(i) });
        };

        setlistData([...lines]);
        setIsMounted(true);
    }

    return { LoadPage };
};
